  for (i = 0; i < n; i++) {
    var a = Math.random() * 6.283, v = rnd(60, big ? 240 : 160);
    sc.fx.push({ x: x, y: y - 12, vx: Math.cos(a) * v, vy: Math.sin(a) * v * 0.5 - rnd(80, 180), life: rnd(0.4, 0.8), c: Math.random() < 0.7 ? 0x8fd3ff : 0xffffff });
  }
